/**
 * 飛行物視覺呈現器 v15.0 - Tapered Trails & Glow
 */
export const ProjectileDrawer = {
    draw(ctx: CanvasRenderingContext2D, op: RenderOp, globalTime: number) {
        const { pVisX: x, pVisY: y, pColor: color, pAngle: angle, pTrail: trail } = op;

        // 1. 渲染能量尾跡 (Comet Tail Style)
        if (trail && trail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';

            // Draw trail segments with tapering width/opacity
            const len = trail.length;
            // Draw from Head (x,y) backwards
            let prevX = x;
            let prevY = y;

            // Use quadratic curves for smoother trails if speed is high
            ctx.beginPath();
            ctx.moveTo(x, y);

            for (let i = 0; i < len; i++) {
                const p = trail[i];
                ctx.lineTo(p.x, p.y);
            }

            // Gradient along the path
            const tailEnd = trail[len-1];
            const grad = ctx.createLinearGradient(x, y, tailEnd.x, tailEnd.y);
            grad.addColorStop(0, color);
            grad.addColorStop(0.3, color); // Keep head solid
            grad.addColorStop(1, 'transparent'); // Fade out tail

            ctx.strokeStyle = grad;
            // Width tapers based on scale
            ctx.lineWidth = (op.pIsUlt ? 10 : 5) * op.pScale;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.globalAlpha = 0.7;
            ctx.stroke();

            // Core bright line for laser feel
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1 * op.pScale;
            ctx.globalAlpha = 0.5;
            ctx.stroke();

            ctx.restore();
        }

        // 2. 主體精靈渲染
        ctx.save();
        ctx.translate(x, y);

        // Stretch based on speed approximation? Just standard stretch for now.
        const stretch = 1.0; 

        if (op.pSpin !== 0) {
            ctx.rotate(op.pSpin);
        } else {
            ctx.rotate(angle);
            ctx.scale(stretch, 1.0 / stretch); 
        }

        const img = AssetManager.getProjectile(op.pSkillVis, color);

        // Use the smaller scale passed from logic
        const baseScale = op.pScale;
        const finalScale = (op.pIsUlt ? 1.5 : 1.0) * baseScale;

        if (img) {
            // Glow pass (Additive)
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 1.0;
            // Draw slightly larger for bloom
            ctx.drawImage(img, -36 * finalScale, -36 * finalScale, 72 * finalScale, 72 * finalScale);

            // Core pass (Source Over) - Ensures the projectile has a defined shape
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = 1.0;
            ctx.drawImage(img, -32 * finalScale, -32 * finalScale, 64 * finalScale, 64 * finalScale);
        } else {
            // Fallback
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0,0, 10 * finalScale, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();

        // 3. 核心亮點 (Head Flare)
        ctx.save();
        ctx.translate(x, y);
        ctx.globalCompositeOperation = 'lighter';
        const flare = ctx.createRadialGradient(0,0,0, 0,0, 25 * op.pScale);
        flare.addColorStop(0, '#ffffff');
        flare.addColorStop(0.4, color);
        flare.addColorStop(1, 'transparent');
        ctx.fillStyle = flare;
        ctx.globalAlpha = 0.9;
        ctx.beginPath(); ctx.arc(0,0, 25 * op.pScale, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    }
};

import { RenderOp } from "./RenderList";
import { AssetManager } from "../assets";

/**
 * 飛行物視覺呈現器 v16.0 - Faction Distinct Styles
 */
export const ProjectileDrawer = {
    draw(ctx: CanvasRenderingContext2D, op: RenderOp, globalTime: number) {
        const { pVisX: x, pVisY: y, pColor: color, pAngle: angle, pTrail: trail } = op;

        // Detect Style based on Color (Heuristic)
        // Blue/Cyan/White = Imperial (Tech/Energy)
        // Red/Orange/Purple = Covenant (Chaos/Blood)
        const isCovenant = color.includes('#ef') || color.includes('#dc') || color.includes('#b9') || color.includes('#7f') || color.includes('#ea') || color.includes('#58');

        // 1. 渲染能量尾跡 (Faction Specific Trails)
        if (trail && trail.length > 1) {
            ctx.save();

            if (isCovenant) {
                // --- COVENANT TRAIL (Smoky, Tapered, Heavy) ---
                ctx.globalCompositeOperation = 'source-over'; // Opaque/Darker feel
                const len = trail.length;

                // Draw multiple segments with varying width for "smoke" effect
                for (let i = 0; i < len - 1; i++) {
                    const p1 = trail[i];
                    const p2 = trail[i+1];
                    const progress = i / len; // 0.0 (Head) -> 1.0 (Tail)

                    ctx.beginPath();
                    ctx.moveTo(p1.x, p1.y);
                    ctx.lineTo(p2.x, p2.y);

                    // Tapering Width: Thick at head, very thin at tail
                    const width = (op.pIsUlt ? 16 : 8) * (1 - progress) * op.pScale;

                    ctx.lineWidth = width;
                    ctx.lineCap = 'round';
                    ctx.strokeStyle = color;
                    ctx.globalAlpha = (1 - progress) * 0.6; // Fade out
                    ctx.stroke();
                }

                // Inner Core (Hot)
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.moveTo(x, y);
                for (let i = 0; i < len; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }
                ctx.strokeStyle = '#fca5a5'; // Pale Red Core
                ctx.lineWidth = (op.pIsUlt ? 4 : 2) * op.pScale;
                ctx.globalAlpha = 0.4;
                ctx.stroke();

            } else {
                // --- IMPERIAL TRAIL (Clean, Electric, Additive) ---
                ctx.globalCompositeOperation = 'screen';

                ctx.beginPath();
                ctx.moveTo(x, y);
                for (let i = 0; i < trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }

                const trailGrad = ctx.createLinearGradient(x, y, trail[trail.length-1].x, trail[trail.length-1].y);
                trailGrad.addColorStop(0, color);
                trailGrad.addColorStop(0.2, color); 
                trailGrad.addColorStop(1, 'transparent');

                ctx.strokeStyle = trailGrad;
                // Constant Width "Laser" look
                ctx.lineWidth = (op.pIsUlt ? 10 : 5) * op.pScale;
                ctx.lineCap = 'butt'; // Sharp ends
                ctx.lineJoin = 'miter';
                ctx.globalAlpha = 0.8;
                ctx.stroke();

                // Core bright line (The "Filament")
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = (op.pIsUlt ? 3 : 1.5) * op.pScale;
                ctx.globalAlpha = 0.6;
                ctx.stroke();
            }

            ctx.restore();
        }

        // 2. 主體精靈渲染
        ctx.save();
        ctx.translate(x, y);

        // Stretch: Imperial projects are faster/longer visually
        const stretch = isCovenant ? 1.05 : 1.3; 

        if (op.pSpin !== 0) {
            ctx.rotate(op.pSpin);
        } else {
            ctx.rotate(angle);
            ctx.scale(stretch, 1.0 / stretch); 
        }

        const img = AssetManager.getProjectile(op.pSkillVis, color);
        const baseScale = op.pScale;
        const finalScale = (op.pIsUlt ? 1.5 : 1.0) * baseScale;

        if (img) {
            // Glow pass
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = isCovenant ? 0.8 : 1.0; // Imperial is brighter
            const bloomScale = isCovenant ? 1.2 : 1.5; // Imperial blooms more
            ctx.drawImage(img, -36 * finalScale * bloomScale, -36 * finalScale * bloomScale, 72 * finalScale * bloomScale, 72 * finalScale * bloomScale);

            // Core pass
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = 1.0;
            ctx.drawImage(img, -32 * finalScale, -32 * finalScale, 64 * finalScale, 64 * finalScale);
        } else {
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0,0, 10 * finalScale, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();

        // 3. 頭部光暈 (Head Flare)
        ctx.save();
        ctx.translate(x, y);
        ctx.globalCompositeOperation = 'lighter';

        const flareR = (isCovenant ? 20 : 30) * op.pScale;
        const flare = ctx.createRadialGradient(0,0,0, 0,0, flareR);

        if (isCovenant) {
            // Red Core
            flare.addColorStop(0, '#fff');
            flare.addColorStop(0.4, color);
            flare.addColorStop(1, 'transparent');
        } else {
            // Blue/White Star
            flare.addColorStop(0, '#ffffff');
            flare.addColorStop(0.3, color);
            flare.addColorStop(1, 'transparent');
        }

        ctx.fillStyle = flare;
        ctx.globalAlpha = 0.9;
        ctx.beginPath(); ctx.arc(0,0, flareR, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    }
};

import { GeometryPainter } from "./GeometryPainter";

export const ProjectilePainter = {
    drawImperialSniper(ctx: CanvasRenderingContext2D, color: string) {
        // Tech Dart / Kinetic Rod
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        // Inner Core
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.moveTo(25, 0); 
        ctx.lineTo(-15, -4);
        ctx.lineTo(-15, 4);
        ctx.fill();

        // Energy Shell
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(30, 0);
        ctx.lineTo(-10, -6);
        ctx.lineTo(-20, 0);
        ctx.lineTo(-10, 6);
        ctx.closePath();
        ctx.stroke();

        // Mach Rings
        ctx.globalAlpha = 0.5;
        ctx.beginPath(); ctx.arc(10, 0, 4, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.stroke();
    },

    drawImperialCrystal(ctx: CanvasRenderingContext2D, color: string) {
        // Faceted Diamond
        ctx.fillStyle = '#e0f2fe';
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(20, 0); 
        ctx.lineTo(0, -8); 
        ctx.lineTo(-10, 0); 
        ctx.lineTo(0, 8);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Highlights
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.moveTo(15, 0); ctx.lineTo(0, -4); ctx.lineTo(0, 4); ctx.fill();
    },

    drawImperialOrb(ctx: CanvasRenderingContext2D, color: string) {
        // Perfect Sphere with Halo
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 10);
        grad.addColorStop(0, '#fff'); grad.addColorStop(0.5, color); grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI * 2); ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.ellipse(0, 0, 14, 4, 0, 0, Math.PI * 2); ctx.stroke();
        ctx.beginPath(); ctx.ellipse(0, 0, 14, 4, Math.PI/2, 0, Math.PI * 2); ctx.stroke();
    },

    drawCovenantBolt(ctx: CanvasRenderingContext2D, color: string) {
        // Jagged Harpoon / Rusty Metal
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        ctx.fillStyle = '#450a0a'; // Dark Iron
        ctx.beginPath();
        ctx.moveTo(20, 0); 
        ctx.lineTo(-10, -8); 
        ctx.lineTo(-5, -2);
        ctx.lineTo(-20, -4); // Jagged tail
        ctx.lineTo(-20, 4);
        ctx.lineTo(-5, 2);
        ctx.lineTo(-10, 8);
        ctx.fill();

        ctx.strokeStyle = color; // Burning edge
        ctx.lineWidth = 2;
        ctx.stroke();
    },

    drawCovenantAxe(ctx: CanvasRenderingContext2D, color: string) {
        // Spinning Blade
        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;

        ctx.beginPath();
        // Axe Head 1
        ctx.moveTo(5, -5); ctx.bezierCurveTo(15, -20, -15, -20, -5, -5);
        // Axe Head 2
        ctx.moveTo(5, 5); ctx.bezierCurveTo(15, 20, -15, 20, -5, 5);
        ctx.fill();
        ctx.stroke();

        // Center rivet
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0,0,4,0,Math.PI*2); ctx.fill();
    },

    drawCovenantFireball(ctx: CanvasRenderingContext2D, color: string) {
        // Unstable Core
        ctx.shadowColor = color;
        ctx.shadowBlur = 25;

        const grad = ctx.createRadialGradient(0, 0, 2, 0, 0, 14);
        grad.addColorStop(0, '#fff'); 
        grad.addColorStop(0.2, '#fca5a5'); 
        grad.addColorStop(0.6, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;

        // Chaotic shape
        GeometryPainter.drawJaggedShape(ctx, 16);
    },

    drawBomb(ctx: CanvasRenderingContext2D, color: string) {
        // Physical Bomb
        ctx.fillStyle = '#1e293b'; 
        ctx.strokeStyle = '#94a3b8'; 
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

        // Fuse spark
        ctx.fillStyle = '#ef4444';
        ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 10;
        ctx.beginPath(); ctx.arc(8, -8, 3, 0, Math.PI * 2); ctx.fill();
    }
};

