export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    constructor(renderer: GameRenderer) { this.renderer = renderer; }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }
    public update(dt: number, engine: GameEngine) { this.tacticalRenderer.update(dt, engine); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width, physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;
        const dpr = window.devicePixelRatio || 1, logicalWidth = physicalWidth / dpr, logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene, layout = engine.mapConfig.layout;
        ctx.resetTransform(); ctx.clearRect(0, 0, physicalWidth, physicalHeight); ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainHeightFunc, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainHeightFunc, globalTime, highlight, engine.mapConfig);
        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i], snapX = Math.round(op.tx), snapY = Math.round(op.ty);
            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    // [FIXED ORDER] Draw Details BEFORE Overlays to prevent detail texture from covering the glow
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, snapY - op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, undefined, layout);
                    break;
                case RenderOpType.HAZARD: 
                    if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time);
                    break;
                case RenderOpType.OBSTACLE:
                    ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    // Fix: Pass op.z (Physics Z) instead of op.th (Terrain Height)
                    // op.ty is already adjusted by terrain height (py - th), so passing th again as z caused double height offset
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.z, op.time, op.uSelected, op.uSilhouette, layout);
                    break;
                case RenderOpType.DECAL:
                    ctx.save(); ctx.translate(snapX, snapY); ctx.scale(op.dScale, op.dScale); ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64); ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) { ctx.save(); ctx.translate(snapX, snapY); ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout); ctx.restore(); }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) occludedAgents.forEach(agent => this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig));
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        ctx.restore(); 
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 
        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);
        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {

    /**
     * SSOT: Calculate standard isometric visual Y.
     * Subtracts Z (height) from Y (ground) to project into 2D screen space.
     */
    public static getIsoVisualY(y: number, z: number): number {
        return y - z;
    }

    /**
     * SSOT: Calculate the visual Y coordinate of the unit's body center.
     * Takes into account surface Y, physics Z (jump), and model offsets.
     */
    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        // surfaceY is typically (WorldY - TerrainHeight)
        // We further subtract physics Z and offsets
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    /**
     * 獲取單位的「核心錨點」(通常是胸口)
     * 用於投射物命中、雷射連接
     */
    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);

        // 胸口高度計算：基礎偏移 + 物理高度 + 模型高度的 40%
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;

        return { x: agent.px, y: agent.py, z: z };
    }

    /**
     * 獲取單位的「腳底錨點」
     * 用於地面法陣、影子、傳送門
     */
    public static getUnitFeet(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        return { x: agent.px, y: agent.py, z: terrainH + agent.physics.z + 2 }; // +2 解決穿插
    }

    public static getHexCenter(q: number, r: number, engine: GameEngine): Point3D {
        const p = HexUtils.toPx(q, r, engine.mapConfig);
        const h = engine.map.getTerrainHeight(q, r);
        return { x: p.x, y: p.y, z: h + 2 }; // 地面特效默認抬高 2px 避免 Z-fighting
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };

        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) {
            return this.getUnitAnchor(agent, engine);
        }

        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                return this.getHexCenter(q, r, engine);
            }
        }

        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. 獲取身體中心視覺 Y 軸 (SSOT)
        // 直接讀取 Agent 物理狀態，避免外部傳遞錯誤
        const pz = agent.physics.z;
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 2. 核心受擊幾何處理 (Juice Math)
        let hitBrightness = 0;
        let squashX = 1.0;
        let squashY = 1.0;

        if (agent.hitFlashTimer > 0 && !isSilhouette) {
            const trauma = agent.hitFlashTimer / 0.2; // 歸一化進度
            // 數學擠壓：受擊時垂直縮短，水平伸長
            squashY = 1.0 - (trauma * 0.25);
            squashX = 1.0 + (trauma * 0.15);
            // 亮度震盪函數 (高頻率 40Hz)
            hitBrightness = 100 + Math.sin(t * 40) * 50;
        }

        ctx.scale(UNIT_SCALE * squashX, UNIT_SCALE * squashY);
        ctx.rotate(agent.physics.angle); 

        // 3. 基礎呼吸與浮動
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 4. 進場縮放動畫
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 5. 狀態濾鏡應用
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(70%)'; 
        } else if (hitBrightness > 0) {
             ctx.filter = `brightness(${hitBrightness}%) contrast(120%)`;
        }

        // 6. 飛行與特殊模型渲染
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";
import { HexLayout } from "../../../../../types";

const HOVER_LIFT = 6; 

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, t: number, isSilhouette: boolean, layout: HexLayout) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // Uses agent.physics.z directly (SSOT)
        const jumpHeight = agent.physics.z;

        // 調低基礎透明度從 1.0 降至 0.35，避免呈現全黑塊
        const shadowScale = Math.max(0.4, 1.0 - (jumpHeight / 500));
        const shadowAlpha = Math.max(0.05, 0.35 - (jumpHeight / 300));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,1)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.globalCompositeOperation = 'multiply'; // 使用色彩增值模式讓陰影與地表融合

        const w = 110; // 稍微放寬陰影範圍增加柔和感
        const h = w * ISO_SCALE_Y;
        ctx.drawImage(shadowBlob, -w/2, -h/2, w, h); 
        ctx.restore();

        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.tag === 'ULT') {
                UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t, layout);
            } else {
                UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t, layout);
            }
        }

        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        if (agent.hp > 0) {
            ctx.save();
            ctx.translate(px, tokenY);
            ctx.scale(UNIT_SCALE, UNIT_SCALE); 

            const iconBaseY = -20; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            ctx.fillStyle = 'rgba(0,0,0,0.2)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';

                if (isAOE && radius > 0) {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, radius, skill.tag, isAOE, layout);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { Agent, GameEngine } from "../game";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { MapConfig } from "../utils";
import { UnitVisualProcessor } from "./unit/UnitVisualProcessor";
import { UnitBodyPainter } from "../renderers/units/painters/UnitBodyPainter";
import { UnitShadowPainter } from "../renderers/units/painters/UnitShadowPainter";
import { HexLayout } from "../../types";
import { VisualMath } from "../math/VisualMath";

export class UnitRenderSystem {
    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;
            const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, highlightAgent);

            const op = renderList.next();
            op.type = RenderOpType.UNIT;

            // 關鍵：將單位的當前邏輯網格位置傳入
            op.tq = agent.q; 
            op.tr = agent.r;
            op.th = state.terrainHeight; 

            op.agent = agent;
            op.tx = state.x; 

            // Sort Y: Ground position for depth sorting
            op.y = state.y; 

            // Visual Y: Top of terrain (using SSOT Math)
            op.ty = VisualMath.getIsoVisualY(state.y, state.terrainHeight);

            op.z = agent.physics.z; 
            op.time = globalTime;
            op.uSelected = state.isSelected;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, null);
        const visualGroundY = VisualMath.getIsoVisualY(state.y, state.terrainHeight);
        this.drawAssembly(ctx, agent, state.x, visualGroundY, globalTime, false, true, mapConfig.layout);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean,
        layout: HexLayout
    ) {
        ctx.save();
        ctx.translate(drawX, drawY); 

        // drawY is expected to be the Surface Visual Y.
        // Painters will internally read agent.physics.z via VisualMath to calculate offsets.

        if (!isSilhouette && agent.hp > 0) {
            UnitShadowPainter.draw(ctx, agent, 0, 0, globalTime, isSilhouette, layout);
        }
        UnitBodyPainter.draw(ctx, agent, 0, 0, globalTime, isSilhouette, isSelected, 1.0);

        ctx.restore(); 
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { HazardPainter } from "./grid/painters/HazardPainter"; 
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    constructor(renderer: GameRenderer) { this.renderer = renderer; }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }
    public update(dt: number, engine: GameEngine) { this.tacticalRenderer.update(dt, engine); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width, physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;
        const dpr = window.devicePixelRatio || 1, logicalWidth = physicalWidth / dpr, logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene, layout = engine.mapConfig.layout;
        ctx.resetTransform(); ctx.clearRect(0, 0, physicalWidth, physicalHeight); ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainHeightFunc, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainHeightFunc, globalTime, highlight, engine.mapConfig);
        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i], snapX = Math.round(op.tx), snapY = Math.round(op.ty);
            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    // [FIXED ORDER] Draw Details BEFORE Overlays to prevent detail texture from covering the glow
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, snapY - op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, undefined, layout);
                    break;
                case RenderOpType.HAZARD: 
                    if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time);
                    break;
                case RenderOpType.OBSTACLE:
                    ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    // Fix: Removed op.z (and mistaken op.th) passing. 
                    // DrawAssembly now relies on VisualMath SSOT to project unit height internally.
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette, layout);
                    break;
                case RenderOpType.DECAL:
                    ctx.save(); ctx.translate(snapX, snapY); ctx.scale(op.dScale, op.dScale); ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64); ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) { ctx.save(); ctx.translate(snapX, snapY); ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout); ctx.restore(); }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) occludedAgents.forEach(agent => this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig));
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        ctx.restore(); 
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 
        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);
        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {

    /**
     * SSOT: Rendering Layer Bias (Negative Y moves UP on screen)
     * Used to prevent Z-fighting on the flat ground plane.
     * Higher "Lift" means it draws "Above" the layer below it.
     */
    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,        // Slightly above terrain
        OVERLAY: 5,       // Above hazards (Grids, Ranges)
        SHADOW: 8,        // Shadows overlay everything on ground
        UNIT_FEET: 0      // Logical reference point
    };

    /**
     * SSOT: Calculate standard isometric visual Y.
     * Subtracts Z (height) from Y (ground) to project into 2D screen space.
     */
    public static getIsoVisualY(y: number, z: number): number {
        return y - z;
    }

    /**
     * SSOT: Apply a specific layer bias to a Visual Y coordinate.
     * Effectively "Lifts" the sprite up by N pixels to sort above the ground.
     */
    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        // In screen space, UP is negative Y. So we subtract the bias.
        return visualY - this.Z_LAYERS[layer];
    }

    /**
     * SSOT: Calculate the visual Y coordinate of the unit's body center.
     * Takes into account surface Y, physics Z (jump), and model offsets.
     */
    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        // surfaceY is typically (WorldY - TerrainHeight)
        // We further subtract physics Z and offsets
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    /**
     * 獲取單位的「核心錨點」(通常是胸口)
     * 用於投射物命中、雷射連接
     */
    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);

        // 胸口高度計算：基礎偏移 + 物理高度 + 模型高度的 40%
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;

        return { x: agent.px, y: agent.py, z: z };
    }

    /**
     * 獲取單位的「腳底錨點」
     * 用於地面法陣、影子、傳送門
     */
    public static getUnitFeet(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        return { x: agent.px, y: agent.py, z: terrainH + agent.physics.z + 2 }; // +2 解決穿插
    }

    public static getHexCenter(q: number, r: number, engine: GameEngine): Point3D {
        const p = HexUtils.toPx(q, r, engine.mapConfig);
        const h = engine.map.getTerrainHeight(q, r);
        return { x: p.x, y: p.y, z: h + 2 }; // 地面特效默認抬高 2px 避免 Z-fighting
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };

        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) {
            return this.getUnitAnchor(agent, engine);
        }

        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                return this.getHexCenter(q, r, engine);
            }
        }

        return { x: 0, y: 0, z: -9999 };
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { SpriteManager } from "../../sprites";
import { VisualMath } from "../../math/VisualMath";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

/**
 * 網格渲染提交策略 - v11.1 (SSOT Strict Compliance)
 */
export class GridRenderStrategy {

    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualBaseY = py + offset;

            // SSOT: Use standard projection
            const visualSurfaceY = VisualMath.getIsoVisualY(visualBaseY, h);

            if (Math.abs(offset) > 800) continue;

            // 1. 提交障礙物
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = py; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // 2. 提交地面效果 (Hazards) -> 從 Terrain 解耦，建立獨立 Op
            const hazard = engine.map.getHazardAt(q, r, engine);
            if (hazard) {
                const hOp = renderList.next();
                hOp.type = RenderOpType.HAZARD;
                hOp.y = py; 
                hOp.z = 5; // 低於單位，高於地板
                hOp.tx = px; 
                // Note: HazardPainter will apply its own Z_LAYER bias internally
                hOp.ty = visualSurfaceY; 
                hOp.oHazard = hazard;
                hOp.time = globalTime;
            }

            // 3. 提交地形與基礎 Overlays
            const zoneInfo = engine.zones.getZoneAt(q, r);
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});
                if (dist <= hoveredSkill.range + bonus) { isRange = true; rangeColor = hoveredSkill.color; }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);

            // 投射物光照計算
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = py; 
            op.z = 0; 
            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset } from "../utils";
import { Projectile } from "../../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath, Point3D } from "../../../math/TrajectoryMath";
import { VisualMath } from "../../../math/VisualMath";
import { ISO_SCALE_Y } from "../../../../constants";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        const now = engine.battleTime;

        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const def: ProjectileVisualDef = PROJECTILE_VISUALS[p.skill.visualProjectileEffect || p.skill.visual || 'BOLT'] || DEFAULT_PROJECTILE;

            // 1. 建立解析座標函數
            const startP: Point3D = { x: p.startX, y: p.startY, z: p.startZ || 30 };
            const targetP = VisualMath.resolveTargetPoint(p.targetId, engine);

            // 安全邊界處理
            let endP: Point3D = targetP;
            if (endP.z < -9000) {
                 const h = engine.map.getTerrainHeight(HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig).q, HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig).r);
                 endP = { x: p.targetPos.x, y: p.targetPos.y, z: h + 25 };
            }

            const dx = endP.x - startP.x;
            const dy = endP.y - startP.y;
            const totalDist = Math.sqrt(dx*dx + dy*dy);

            const duration = totalDist / Math.max(50, p.speed); // Prevent divide by zero
            const age = now - p.createdAt;
            const t = Math.min(1.0, age / duration);

            const getPosAt = (progress: number) => {
                if (def.trajectory === 'ARC') {
                    // [UPDATED] Dynamic Arc Height: Scale with distance, clamped between min and max
                    // Short throws are low, long throws are high.
                    const dynamicHeight = Math.min(def.arcHeight || 150, Math.max(30, totalDist * 0.35));
                    return TrajectoryMath.parabolic(startP, endP, progress, dynamicHeight);
                }
                if (def.trajectory === 'WOBBLE') return TrajectoryMath.wobble(startP, endP, progress, def.wobbleAmp || 15, def.wobbleFreq || 2);
                return TrajectoryMath.linear(startP, endP, progress);
            };

            const pos3D = getPosAt(t);
            const visAngle = TrajectoryMath.getProjectedAngle(getPosAt, t, 1.0);

            // 2. 計算視覺座標 (等角投影)
            const transOffset = getTransitionOffset(pos3D.x, pos3D.y, engine.mapConfig, transitionT, transitionPhase);
            const visX = pos3D.x;

            // SSOT Enforcement: Use VisualMath for projection
            const visY = VisualMath.getIsoVisualY(pos3D.y, pos3D.z) + transOffset;

            // 3. 提交渲染指令
            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;

            // 核心優化：飛行物 Y 排序偏置。
            op.y = pos3D.y; 
            op.z = 5000 + pos3D.z; 

            op.pVisX = visX;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = def.spinSpeed ? (age * def.spinSpeed) : 0;
            op.pScale = def.scale || 1.0; 

            // 4. 解析尾跡採樣 (Analytic Trail Sampling)
            op.pTrail = [];
            const trailSamples = def.trailLength || 0;
            if (trailSamples > 0) {
                // [UPDATED] Trail sampling relative to speed for smoother curves
                const step = 0.015; 
                for (let i = 1; i <= trailSamples; i++) {
                    const tPast = Math.max(0, t - i * step);
                    const past3D = getPosAt(tPast);

                    // SSOT Enforcement here too
                    const pastY = VisualMath.getIsoVisualY(past3D.y, past3D.z) + transOffset;

                    op.pTrail.push({ x: past3D.x, y: pastY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { VisualMath } from "../../../math/VisualMath";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        let fade = 1.0;
        if (hazard.duration < 0.8) fade = hazard.duration / 0.8;

        ctx.save();
        ctx.globalAlpha = fade;

        // SSOT: Use centralized Z-Layer bias
        const drawY = VisualMath.applyLayerBias(y, 'HAZARD');

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            // Increased scale for visibility
            const size = HEX_SIZE * 3.0; 
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, drawY - 15); // Fog floats a bit higher naturally
            ctx.scale(1, ISO_SCALE_Y);

            // 1. Base Body (Darker, Opaque-ish) for Volume
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = def.intensity * 0.3;
            ctx.drawImage(texture, -size * 0.3, -size * 0.3, size * 0.6, size * 0.6);

            // 2. Swirling Light Layers
            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';

            ctx.save();
            ctx.rotate(speed * 0.12);
            ctx.globalAlpha = def.intensity * 0.6;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.save();
            ctx.rotate(-speed * 0.08 + 2.0);
            ctx.scale(0.9, 0.9);
            ctx.globalAlpha = def.intensity * 0.4;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);

            ctx.save();
            ctx.translate(0, 0); // No extra translate, drawY is passed

            // Base Puddle
            SurfacePainter.drawLiquid(ctx, x, drawY, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, drawY, def.secondaryColor, intensity * 0.8);

            // Rising Heat/Flames (Visual Boost)
            if (hazard.type === 'FIRE') {
                const flameTex = VFXFactory.getTexture('SMOKE', '#fca5a5'); // Bright core color
                const flameH = 60;
                const flameW = 40;
                const rise = (globalTime * 50) % 30;

                ctx.translate(x, drawY - 10 - rise);
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = (1 - rise/30) * intensity;

                // Draw 2 flame tongues
                ctx.drawImage(flameTex, -flameW/2, -flameH, flameW, flameH);
                ctx.drawImage(flameTex, -flameW * 0.3, -flameH * 0.8, flameW * 0.6, flameH * 0.8);
            }

            ctx.restore();
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, drawY, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7);

            ctx.save();
            ctx.translate(x, drawY - 5); 
            ctx.scale(1, ISO_SCALE_Y);
            const texture = VFXFactory.getTexture('ROCK', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.6;
            ctx.drawImage(texture, -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.scale(1, ISO_SCALE_Y);

            // Massive Radius
            const r = HEX_SIZE * 1.6;

            // 1. The Void (Pitch Black Core) - Source Over to eat pixels
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = '#000';
            ctx.beginPath(); ctx.arc(0, 0, r * 0.6, 0, Math.PI*2); ctx.fill();

            // 2. Event Horizon (Purple Ring)
            ctx.globalCompositeOperation = 'lighter';
            ctx.lineWidth = 4;
            ctx.strokeStyle = def.secondaryColor;
            ctx.shadowColor = def.secondaryColor;
            ctx.shadowBlur = 20;

            const rot = globalTime * 3;
            ctx.save();
            ctx.rotate(rot);
            // Spiral draw
            ctx.beginPath();
            for(let i=0; i<3; i++) {
                const ang = i * (Math.PI*2/3);
                ctx.moveTo(0,0);
                ctx.quadraticCurveTo(Math.cos(ang)*r, Math.sin(ang)*r, Math.cos(ang+1)*r, Math.sin(ang+1)*r);
            }
            ctx.stroke();
            ctx.restore();

            // 3. Accretion Disk Gradient
            const grad = ctx.createRadialGradient(0, 0, r * 0.5, 0, 0, r);
            grad.addColorStop(0, def.secondaryColor);
            grad.addColorStop(0.5, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.6;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            ctx.restore();
        }

        ctx.restore();
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexUtils } from "../../utils";
import { VisualMath } from "../../math/VisualMath";

export const GridOverlays = {
    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,
        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined, 
        layout: HexLayout
    ) {
        // SSOT: Use centralized Z-Layer bias for overlays
        const drawY = VisualMath.applyLayerBias(y, 'OVERLAY');

        // 1. 狀態地效
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, drawY);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        // 2. 戰術區域 (奧義預警/AOE 範圍)
        if (zoneInfo) {
            const dist = HexUtils.dist({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, drawY - 1, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy,
                layout
            );
        }

        // 3. 點光源投影
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        // 4. 交互高亮
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, drawY + 1); 
            ctx.globalCompositeOperation = 'screen';
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.12;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
                ctx.fill();
                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }
            if (isHover) { 
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }
            ctx.restore();
        }
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";
import { HexLayout } from "../../../../../types";
import { VisualMath } from "../../../math/VisualMath";

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, t: number, isSilhouette: boolean, layout: HexLayout) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;

        // SSOT: Use centralized shadow bias
        const tokenY = VisualMath.applyLayerBias(surfaceY, 'SHADOW');

        ctx.save();

        // Uses agent.physics.z directly (SSOT)
        const jumpHeight = agent.physics.z;

        // 調低基礎透明度從 1.0 降至 0.35，避免呈現全黑塊
        const shadowScale = Math.max(0.4, 1.0 - (jumpHeight / 500));
        const shadowAlpha = Math.max(0.05, 0.35 - (jumpHeight / 300));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,1)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.globalCompositeOperation = 'multiply'; // 使用色彩增值模式讓陰影與地表融合

        const w = 110; // 稍微放寬陰影範圍增加柔和感
        const h = w * ISO_SCALE_Y;
        ctx.drawImage(shadowBlob, -w/2, -h/2, w, h); 
        ctx.restore();

        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.tag === 'ULT') {
                UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t, layout);
            } else {
                UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t, layout);
            }
        }

        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        if (agent.hp > 0) {
            ctx.save();
            ctx.translate(px, tokenY);
            ctx.scale(UNIT_SCALE, UNIT_SCALE); 

            const iconBaseY = -20; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            ctx.fillStyle = 'rgba(0,0,0,0.2)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';

                if (isAOE && radius > 0) {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, radius, skill.tag, isAOE, layout);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

